   "text": "这一章讲第三条路，也是最激进的一条：**不换变量，不换维数，而是换掉最基本的元素。**\n先看它要换掉什么。前面所有章节的几何，以及你从小到大的空间经验，都建立在一个假设上：空间是由「点」组成的，你可以指着某一处说「就在这里」。扭量理论说：**别先问「粒子在哪里」，先问「哪一束光线经过它」。** 把光线本身当作最基本的对象，时空点反而成了派生物。\n这个换法有道理。你回想第 17 章：相对论里真正基本的结构就是光锥、就是光线；而量子力学里那个「精确的位置」其实是一个理想化的极限。两边的麻烦都落在同一个词上——**点**。\n本章会给你两个结论。第一个是漂亮的：在这个语言里，光线变成点，而时空点变成一个球面，整个几何的重心从一个层次转移到另一个层次。第二个是克制的：这条路至今不是主流，而且它最自然的栖息地是共形结构，可真实的时空不是共形平坦的。"
