   "h": "33.1 带离散元素的几何理论（续）",
   "orig": "另有一批想法，思路与最初的自旋网络或自旋泡沫方案大不相同，目标同样是给出一幅完全离散／组合的世界图景。其中较奇特的一个（16.1 节已提过）出自 Ahmavaara（1965）：把常规物理数学所依赖的实数系统换成某个有限域 F_p，p 是某个极其巨大的素数——按 16.1 节的说法，F_p 就是整数模 p 的系统。还有些方案让时空带上离散的周期点阵结构，像一堆立方体规规矩矩叠起来的顶点（图 33.1）。物理上可信得多的是 Raphael Sorkin 的因果集几何（causal-set geometry），以及若干密切相关的更早想法：时空由一组离散、可能有限的点构成，点与点之间的因果关联才是基本概念。用通常的经典语言说，「因果关联」指一点能向另一点发信号，也就是一点落在另一点的光锥上或光锥内（图 33.2）。Sorkin 方案里，因果连接大体是随机的，正因如此，狭义相对论的洛伦兹不变性才可望浮现出来；点阵式结构在这方面麻烦很大，尽管对图 33.1 那样的点阵，这类对称性比乍看之下要多。另一些奇异时空结构来自 David Finklestein 的量子集合论或四元数几何，以及 Corinne Manogue 与 Tevian Dray 的八元数物理（11.2、16.1 节）等等。",
