   "orig": "描述 M# 及其变换群，有个很漂亮的办法。考虑伪欧几里得六维空间 E^{2,4}（符号差 + + − − − −）里原点 O 的「光锥」K。取 E^{2,4} 的标准坐标 w, t, x, y, z, v，K 由方程 w² + t² − x² − y² − z² − v² = 0 给出，度规为 ds² = dw² + dt² − dx² − dy² − dz² − dv²。这是一个以 O 为顶点的五维「锥」。我尽力在图 33.10 里画了它，但图容易误导的地方之一，是看似分成「过去」「未来」两片的 K 其实连成一片。现在用零 5 平面 w − v = 1 去截 K，截口是一个四维流形（「抛物面」），从 E^{2,4} 诱导来的内蕴度规为 ds² = dt² − dx² − dy² − dz²。这正是普通平坦闵氏四维空间的度规形式（18.1 节），所以不妨把它等同于 M，尽管它在 E^{2,4} 里是「弯着」嵌进去的（图 33.10 中像一条抛物线）。那么 M# 在这幅图里是什么？它是 K 的全体母线构成的空间：过 O、躺在 K 上的直线，两个方向的整条直线算作一条母线。于是 M# 的每一点干脆就是 K 的一条母线（图 33.10）——这么一来，M# 就是 E^{2,4} 原点处某个「观察者」的天球！",
