   "h": "33.5 基本扭量几何与坐标（续）",
   "orig": "按 12.8 节的记号，有时用（抽象）指标 Z^a 表示扭量 Z（在标准标架里其分量为 Z⁰, Z¹, Z², Z³）。每个扭量 Z（或 Z^a，T 的元素）都有复共轭 Z̄^a，它是一个对偶扭量（对偶扭量空间 T* 的元素）。指标形式里，Z̄ 写作带下指标的 Z̄_a，分量（标准标架中）为 (Z̄_0, Z̄_1, Z̄_2, Z̄_3) = (Z̄², Z̄³, Z̄⁰, Z̄¹)，右边四个分别是 Z², Z³, Z⁰, Z¹ 的复共轭。这个记号有点绕：左边四个量（复数）只是对偶扭量 Z̄ 的四个分量，右边的四个是 Z², Z³, Z⁰, Z¹ 各自的复共轭——所以 Z̄ 的分量 Z̄_0 是 Z 的分量 Z² 的复共轭，依此类推。注意构成复共轭时，前两个分量与后两个分量对调了位置。既然 Z̄ 是对偶扭量，就可以拿它与原来的扭量 Z 作（厄米）标量积（见 13.9 节与 22.3 节），得到（平方）扭量范数：Z̄_aZ^a = Z̄_0Z⁰ + Z̄_1Z¹ + Z̄_2Z² + Z̄_3Z³ = Z̄²Z⁰ + Z̄³Z¹ + Z̄⁰Z² + Z̄¹Z³ = ½(|Z⁰+Z²|² + |Z¹+Z³|² − |Z⁰−Z²|² − |Z¹−Z³|²)。最后的式子表明，厄米表达式 Z̄_aZ^a 的符号差是 (+ + − −)，与 13.9 节一致。（扭量空间的对称性体现了 13.10 节提到的局部等价：群 SU(2,2) 与 33.3 节的 O(2,4) 局部等价。）由上面的入射关系可以推出：扭量 Z^a 能与实闵氏空间 M 中的事件相入射，仅当其范数为零，即 Z̄_aZ^a = 0。这时我们说扭量 Z 是零扭量（null）。",
