   "orig": "下面看（图 33.5 所画的）P𝒩 与 M 的几何关系，它是本节开头那个入射关系的推论。从入射关系直接可以看出：与同一个非零扭量 Z（必为零扭量）相入射的 M 的两个点 P、R（事件），必定彼此零间隔，即各自位于对方的光锥上。由此，Z 定义了 M 中的一条光线——一条零直线，因为所有与 Z 相入射的点彼此零间隔（图 33.12）。而且，把 Z^a 换成 λZ^a（λ 为任意非零复数），代表的是同一条光线。与一个（非零）零射影扭量相入射的事件轨迹，确实是一条光线；但 Z² = Z³ = 0 这种特殊情形要另行解读：此时没有 M 中的实际点与之相入射，可我们仍能把这样的零扭量看作描述无穷远处的光线——I 的一条母线，躺在 M# 里而非 M 里。",
