   "orig": "另一个领域是扭量粒子理论。它主要由 Zoltán Perjés、George Sparling、Lane Hughston、Paul Tod 和 Florence Tsou（徐树桐）依据我在 1970 年代中期到 80 年代初引入的想法发展起来，此后大部分时间处于休眠。基本想法是：无质量粒子可以用单个扭量变量的扭量波函数（比如 f(Z^a)）描述，有质量粒子则需要更多变量，例如 X^a, …, Z^a。有质量粒子的动量与角动量由一个表达式给出，把所有这些扭量各自的贡献加起来；但此时多出一个内部对称群，来自这些扭量变量及其复共轭之间那些不影响总动量与总角动量的变换。值得一提的或许是，得到的群包含并略微推广了电弱相互作用的 U(2) 与强相互作用的 SU(3)。人们注意到它与标准模型的粒子分类有若干瞩目的关系，可这个方案因某些技术原因停滞了。看来很有希望：晚近关于「googly 问题」的进展——尤其若能用到规范场上——可以让这个学科重新开张。",
