   "h": "33.14 扭量理论的未来？（续）",
   "orig": "扭量理论有什么明确的「预言」吗？我能想到的最接近预言的一条是：理论的底层动机会蕴涵宇宙应当有负的空间曲率，即 K < 0。理由如下。先回顾第 27、28 章（尤其 27.13 节）：大爆炸似乎异常均匀，与某个 FLRW 模型极为接近。这些模型是共形平坦的（外尔曲率为零），可以用平坦的扭量空间（CP³）非常简单地描述。K > 0、K = 0、K < 0 三种情形各有一个精确的对称群，但只有在 K < 0 时这个群才是全纯群。事实上，那种情形下这个群恰好就是开启扭量理论「复数魔力」的那一个，即洛伦兹群 O(1, 3)——忽略反射时，它是黎曼球面的全纯变换群。这个黎曼球面在哪里？它是双曲三维空间的「无穷远」，就像 Escher 画中的边界圆（图 2.11 复制的那幅），可类比 18.5 节的天球，作为 18.4 节双曲三维空间的边界；见图 18.10。",
